(619, 'SupportSpellCascade', '', 9040, NULL, NULL, NULL, 'Supports spell skills that apply an effect to an area around a targeted location. Cannot support Vaal skills or skills used by totems, traps, or mines. Cannot modify the skills of minions.', '', '[14,4,11,16]', 14657, 5),
(620, 'SupportAncestralCall', '', 9042, NULL, NULL, NULL, 'Supports melee strike skills, causing them to also strike at extra targets simultaneously. The extra targets must be a minimum distance from the user. If supporting a minion attack skill, the minion''s skills will not also strike extra targets. Cannot support Vaal skills or triggered skills.', '', '[9,16,7,13,36]', 14658, 5),
(621, 'SupportSummonPhantasm', '', 9044, NULL, NULL, NULL, 'Supports skills that can hit enemies, or create minions. When those skills or minions kill enemies, or hit rare or unique enemies they will have a chance to summon a Phantasm minion, which uses a piercing projectile spell that deals physical damage.', '', '[11,16,8]', 14659, 5),
(622, 'SupportMirageArcher', '', 9076, NULL, NULL, NULL, 'Supports attack skills that can be used with bows. Supported skills can only be used with bows. Cannot support Vaal skills, minion skills, movement skills, or skills used by totems, traps, or mines.', '', '[6,13,10,16,15]', 14660, 5),
