(777, 'SupportGreaterVolley', '', 10024, NULL, NULL, NULL, 'Supports skills that fire projectiles from the user. Does not affect projectiles fired from other locations as secondary effects. Does not support skills that fire projectiles in a spiral.', '', '[10,16,5]', 14656, 5),
(778, 'SupportAwakenedAddedFireDamage', '', 10887, NULL, NULL, NULL, 'Supports any skill that hits enemies.', '', '[0,33,51,9,16]', 14680, 5),
(779, 'SupportAwakenedAncestralCall', '', 10888, NULL, NULL, NULL, 'Supports melee strike skills, causing them to also strike at extra targets simultaneously. The extra targets must be a minimum distance from the user. If supporting a minion attack skill, the minion''s skills will not also strike extra targets. Cannot support Vaal skills or triggered skills.', '', '[51,9,16,7,13,36]', 14681, 5),
(780, 'SupportAwakenedBrutality', '', 10889, NULL, NULL, NULL, 'Supports any skill that deals damage.', '', '[33,51,9,16]', 14682, 5),
(781, 'SupportAwakenedBurningDamage', '', 10890, NULL, NULL, NULL, 'Supports any skill that hits enemies, or can deal burning damage directly.', '', '[0,51,9,16]', 14683, 5),
(782, 'SupportAwakenedElementalDamageWithAttacks', '', 10891, NULL, NULL, NULL, 'Supports attack skills.', '', '[13,51,9,16]', 14684, 5),
(783, 'SupportAwakenedFirePenetration', '', 10892, NULL, NULL, NULL, 'Supports any skill that hits enemies, making those hits penetrate enemy fire resistance.', '', '[0,51,9,16]', 14685, 5),
(784, 'SupportAwakenedGenerosity', '', 10893, NULL, NULL, NULL, 'Supports aura skills that affect you and allies, increasing the aura''s effect on allies, but preventing it from affecting you at all. Cannot support curse auras, or other auras that only affect enemies. Cannot support skills used by totems. Cannot modify the skills of minions.', '', '[51,9,16,12]', 14686, 5),
(785, 'SupportAwakenedMeleePhysicalDamage', '', 10894, NULL, NULL, NULL, 'Supports melee attack skills.', '', '[7,33,51,9,16,13]', 14687, 5),
(786, 'SupportAwakenedMeleeSplash', '', 10895, NULL, NULL, NULL, 'Supports melee strike skills, causing their melee strike to deal splash damage around each target hit.', '', '[51,9,16,7,13,36,14]', 14688, 5),
(787, 'SupportAwakenedMultistrike', '', 10896, NULL, NULL, NULL, 'Supports melee attack skills, making them repeat three times when used, targeting a random enemy each time. Cannot support Vaal skills, channelling skills, travel skills, retaliation skills or triggered skills.', '', '[13,7,51,9,16]', 14689, 5),
(788, 'SupportAwakenedAddedColdDamage', '', 10897, NULL, NULL, NULL, 'Supports any skill that hits enemies.', '', '[1,51,10,16]', 14690, 5),
(789, 'SupportAwakenedArrowNova', '', 10898, NULL, NULL, NULL, 'Supports bow attack skills that fire arrows forwards as projectiles. These skills will instead fire a payload arrow into the air to land at a targeted location. The supported skills'' arrows will then fire out in a circle from where it lands. Cannot support skills that already fire arrows into the air, channelled skills, or skills that create Minions.', '', '[6,13,51,10,16,5]', 14691, 5),
(790, 'SupportAwakenedCastOnCriticalStrike', '', 10899, NULL, 10900, NULL, 'Must support both an attack skill and a spell skill to work. The attack skill will trigger a spell when it critically strikes an enemy. Cannot support totems, traps, or mines. Vaal skills, channelling skills, and skills with a reservation cannot be triggered.', '', '[47,51,10,16,4,26]', 14692, 5),
(791, 'SupportAwakenedChain', '', 10901, NULL, NULL, NULL, 'Supports projectile skills, and any other skills that chain.', '', '[51,10,16,18,5]', 14693, 5),
(792, 'SupportAwakenedColdPenetration', '', 10902, NULL, NULL, NULL, 'Supports any skill that hits enemies, making those hits penetrate enemy cold resistance.', '', '[1,51,10,16]', 14694, 5),
(793, 'SupportAwakenedDeadlyAilments', '', 10903, NULL, NULL, NULL, 'Supports any skill that hits enemies.', '', '[51,10,16]', 14695, 5),
(794, 'SupportAwakenedFork', '', 10904, NULL, NULL, NULL, 'Supports projectile skills, making their projectiles fork into two projectiles the first two times they hit an enemy and don''t pierce it.', '', '[51,10,16,5]', 14696, 5),
(795, 'SupportAwakenedGreaterMultipleProjectiles', '', 10905, NULL, NULL, NULL, 'Supports projectile skills.', '', '[51,10,16,5]', 14697, 5),
(796, 'SupportAwakenedSwiftAffliction', '', 10906, NULL, NULL, NULL, 'Supports any skill that has a duration, or can hit enemies to inflict ailments on them.', '', '[51,10,16,15]', 14698, 5),
(797, 'SupportAwakenedVoidManipulation', '', 10907, NULL, NULL, NULL, 'Supports any skill that deals damage.', '', '[3,51,10,16]', 14699, 5),
(798, 'SupportAwakenedViciousProjectiles', '', 10908, NULL, NULL, NULL, 'Supports projectile attack skills.', '', '[5,13,33,3,51,10,16]', 14700, 5),
(799, 'SupportAwakenedAddedChaosDamage', '', 10909, NULL, NULL, NULL, 'Supports any skill that hits enemies.', '', '[3,51,11,16]', 14701, 5),
(800, 'SupportAwakenedAddedLightningDamage', '', 10910, NULL, NULL, NULL, 'Supports any skill that hits enemies.', '', '[2,51,11,16]', 14702, 5),
(801, 'SupportAwakenedBlasphemy', '', 10911, NULL, NULL, NULL, 'Supports hex curse skills, turning them into auras that will apply their effect to all enemies in an area around you.', '', '[51,11,16,42,12]', 14703, 5),
(802, 'SupportAwakenedCastWhileChannelling', '', 10912, NULL, 10913, NULL, 'Must support both a channelling skill and a non-channelling spell skill to work. The channelling skill will trigger a spell periodically while channelling. Cannot support skills used by totems, traps, or mines. Vaal skills and skills with a reservation cannot be triggered.', '', '[51,11,16,30,4,26]', 14704, 5),
(803, 'SupportAwakenedControlledDestruction', '', 10914, NULL, NULL, NULL, 'Supports attack skills, or spell skills that deal damage.', '', '[4,47,51,11,16]', 14705, 5),
(804, 'SupportAwakenedHextouch', '', 10915, NULL, 10916, NULL, 'Must support both a skill that hits enemies, and a hex curse skill to work. The hex will be applied when enemies are hit by the other skill. Cannot support totems, traps, or mines. Minions cannot apply hexes this way.', '', '[51,11,16,42,26]', 14706, 5),
(805, 'SupportAwakenedElementalFocus', '', 10917, NULL, NULL, NULL, 'Supports any skill that hits or burns enemies, or inflicts elemental ailments.', '', '[51,11,16]', 14707, 5),
(806, 'SupportAwakenedIncreasedAreaofEffect', '', 10918, NULL, NULL, NULL, 'Supports any skill with an area of effect.', '', '[51,11,16,14]', 14708, 5),
(807, 'SupportAwakenedLightningPenetration', '', 10919, NULL, NULL, NULL, 'Supports any skill that hits enemies, making those hits penetrate enemy lightning resistance.', '', '[2,51,11,16]', 14709, 5),
(808, 'SupportAwakenedMinionDamage', '', 10920, NULL, NULL, NULL, 'Supports skills which create Minions.', '', '[51,11,16,8]', 14710, 5),
(809, 'SupportAwakenedSpellCascade', '', 10921, NULL, NULL, NULL, 'Supports spell skills that apply an effect to an area around a targeted location. Cannot support Vaal skills or skills used by totems, traps, or mines. Cannot modify the skills of minions.', '', '[14,4,51,11,16]', 14711, 5),
(810, 'SupportAwakenedSpellEcho', '', 10922, NULL, NULL, NULL, 'Supports spell skills, making them repeat when cast. Cannot support Vaal skills, totem skills, channelling skills, triggered skills, instant skills, retaliation skills, blink skills, or skills with a reservation.', '', '[4,51,11,16]', 14712, 5),
(811, 'SupportAwakenedUnboundAilments', '', 10923, NULL, NULL, NULL, 'Supports any skill that hits enemies or inflicts ailments', '', '[51,11,16]', 14713, 5),
(812, 'SupportAwakenedUnleash', '', 10924, NULL, NULL, NULL, 'Supports spell skills, making their effect reoccur when cast. Cannot support skills with cooldowns, triggered skills, Brand skills, Vaal skills, channelling skills, skills with a reservation, or skills used by totems, traps, or mines. Cannot modify the skills of minions.', '', '[4,51,11,16]', 14714, 5),
(813, 'SupportAwakenedEmpower', '', 2742, NULL, NULL, NULL, 'Supports any skill gem. Once this gem reaches level 2 or above, will raise the level of supported gems. Cannot support skills that don''t come from gems.', '', '[29,48,51,9,16]', 14715, 5),
(814, 'SupportAwakenedEnlighten', '', 3248, NULL, NULL, NULL, 'Supports any skill gem. Once this gem reaches level 2 or above, will apply a cost & reservation multiplier to supported gems. Cannot support skills that don''t come from gems.', '', '[29,48,51,11,16]', 14716, 5),
(815, 'SupportAwakenedEnhance', '', 3008, NULL, NULL, NULL, 'Supports any skill gem. Once this gem reaches level 2 or above, will raise the quality of supported gems. Cannot support skills that don''t come from gems.', '', '[29,48,51,10,16]', 14717, 5),
