(1003, 'BattlemagesCry', '', 11986, NULL, 11987, NULL, 'Supports spell skills, causing them to be triggered. Cannot support skills used by totems, traps, or mines. Vaal skills, channelling skills, and skills with a reservation cannot be triggered.', 'Battlemage''s Cry Support', '[27,47,26,9,25,14,15]', NULL, 5),
(1004, 'SupportEarthbreaker', '', 11988, NULL, NULL, NULL, 'Supports slam skills, causing them to summon an ancestor totem that uses the skill for you while you''re near it. Being near it grants you increased area of effect for melee skills.', '', '[13,7,40,14,9,16,19]', 14729, 5),
