(1008, 'SupportArrowNovaRoyale', '', 10870, NULL, NULL, NULL, 'Supports bow attack skills that fire arrows forwards as projectiles. These skills will instead fire a payload arrow into the air to land at a targeted location. The supported skills'' arrows will then fire out in a circle from where it lands. Cannot support skills that already fire arrows into the air, channelled skills, or skills that create Minions.', '', '[6,13,10,16,5]', NULL, 5),
(1009, 'SupportBlasphemyRoyale', '', 4806, NULL, NULL, NULL, 'Supports hex curse skills, turning them into auras that will apply their effect to all enemies in an area around you.', '', '[11,16,42,12]', NULL, 5),
(1010, 'SupportCastOnDeathRoyale', '', 2938, NULL, NULL, NULL, 'Each supported spell skill will be triggered when you die. Cannot support skills used by totems, traps, or mines. Vaal skills, channelling skills, and skills with a reservation cannot be triggered.', '', '[10,16,4,26]', NULL, 5),
(1011, 'SupportFistofWarRoyale', '', 11283, NULL, NULL, NULL, 'Supports slam skills, providing a powerful boost when they''re used, with a delay before they can be boosted again. Cannot support Vaal skills or triggered skills. Cannot modify the skills of minions. Only skills you use yourself can receive the boost.', '', '[40,13,7,14,9,16]', NULL, 5),
(1012, 'SupportFortifyRoyale', '', 5024, NULL, NULL, NULL, 'Supports melee attack skills that are not triggered.', '', '[13,9,16,7]', NULL, 5),
